{
  "type": "side-by-side mobile UI mockup",
  "theme": "{argument name=\"app style\" default=\"Chinese mobile live streaming app\"}",
  "panels": [
    {
      "position": "left",
      "subject": "{argument name=\"streamer appearance\" default=\"young Asian woman, beautiful, smiling\"}, long wavy hair, holding a handwritten sign",
      "sign_content": "{argument name=\"sign text\" default=\"谢谢 Ray 的大火箭！\"} with small rocket and heart doodles",
      "ui_elements": {
        "top_bar": "profile info, follow button, 3 viewer avatars, {argument name=\"viewer count\" default=\"10万+\"} count, close button",
        "overlays": "popularity rank badge, gift gallery widget, floating gift animation showing {argument name=\"gift name\" default=\"大火箭\"} x1",
        "chat_stream": "7 distinct chat message bubbles",
        "bottom_bar": "text input field, 4 action icons, floating like hearts"
      }
    },
    {
      "position": "right",
      "subject": "same streamer, high ponytail with scrunchie, holding a handwritten sign",
      "sign_content": "{argument name=\"sign text\" default=\"谢谢 Ray 的大火箭！\"} with stars, hearts, and rocket doodles",
      "ui_elements": {
        "top_bar": "app logo, LIVE badge, 12.6万 viewer count, profile info, follow button",
        "overlays": "hourly rank badge, gift goal widget, 2 floating gift animations (rocket x1, rose x10)",
        "chat_stream": "6 distinct chat message bubbles",
        "bottom_bar": "text input field, 4 action icons, follow button, floating like hearts"
      }
    }
  ]
}

{
  "type": "3D e-commerce livestream promotional poster",
  "style": "vibrant purple and gold color scheme, glossy UI elements, neon lights, soft blurred studio background",
  "typography": {
    "header_pill": "抖音直播",
    "main_title": "{argument name=\"main title\" default=\"直播中\"}",
    "subtitle": "{argument name=\"subtitle\" default=\"欢迎进直播间\"}",
    "promo_pill": "{argument name=\"promo text\" default=\"好物推荐 不止5折\"}"
  },
  "layout": {
    "sections": [
      {
        "title": "feature_cards",
        "position": "middle",
        "count": 3,
        "items": [
          {"icon": "purple price tag", "text": "大牌好货 正品保障"},
          {"icon": "red envelope", "text": "直播专属 优惠多多"},
          {"icon": "purple gift box", "text": "互动抽奖 惊喜不停"}
        ]
      },
      {
        "title": "marquee_sign",
        "position": "lower middle",
        "style": "neon border with glowing dots, 3D red heart icon",
        "text": "{argument name=\"marquee text\" default=\"关注主播 不迷路\"}"
      },
      {
        "title": "footer_pill",
        "position": "bottom center",
        "style": "glowing neon border",
        "text": "{argument name=\"footer text\" default=\"点关注 下单享优先发货\"}"
      }
    ]
  },
  "scene_elements": {
    "top_corners": "2 studio spotlights pointing inwards",
    "bottom_left": "1 ring light on a tripod holding a smartphone",
    "bottom_right": "3 stacked cardboard boxes with labels '极速发货' and '售后无忧', 1 miniature shopping cart, 2 purple gift boxes with yellow ribbons",
    "background": "blurred studio setup with shelves and purple ambient lighting"
  }
}

{
