{
  "type": "two-panel fantasy RPG promotional illustration",
  "global_elements": {
    "main_title": "{argument name=\"main title\" default=\"獣誓界アルドラン\"}",
    "english_subtitle": "{argument name=\"english subtitle\" default=\"Aldran, the Beast-Sworn World\"}",
    "catchphrase": "獣人たちの絆が、世界の運命を切り拓く。",
    "vertical_tagline": "{argument name=\"tagline\" default=\"共に生き、共に誓い、この世界を、未来へ繋ぐ。\"}"
  },
  "characters": [
    {
      "name": "アイラ",
      "description": "winged beast-girl with brown hair and feathered wings",
      "role_label": "斥候 / 遠距離戦闘士",
      "weapon_label": "武器：風切弓"
    },
    {
      "name": "ガルド",
      "description": "massive tiger beastman in heavy plate armor",
      "role_label": "前衛重戦士",
      "weapon_label": "武器：鋼嵐"
    },
    {
      "name": "カラス",
      "description": "wolf-boy with black hair, wolf ears, tail, dark leather armor and cloak",
      "role_label": "リーダー / 近接戦闘士",
      "weapon_label": "武器：牙断"
    },
    {
      "name": "シロ",
      "description": "white fox-girl with long white hair, fox ears, multiple fluffy tails, blue and white robes",
      "role_label": "魔法師 / 回復・補助",
      "weapon_label": "武器：灯魂杖"
    }
  ],
  "layout": {
    "panels": [
      {
        "position": "top half",
        "scene": "{argument name=\"peaceful setting\" default=\"bustling fantasy market town in warm daylight\"}",
        "action": "characters are relaxed, smiling, and eating street food skewers together"
      },
      {
        "position": "bottom half",
        "scene": "{argument name=\"combat setting\" default=\"dark atmospheric forest with glowing magic runes\"}",
        "action": "characters are in dynamic combat stances, weapons drawn, casting magic, tense atmosphere"
      }
    ]
  }
}

